"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["50386"],{59338(e){e.exports=JSON.parse('{"id":"FIN-1331","slug":"regtech","term":"RegTech","also_known_as":[],"difficulty":"Advanced","definition":"RegTech, short for regulatory technology, is the use of technology, such as data analytics, automation and artificial intelligence, to help businesses comply with regulations more efficiently and effectively.","explanation":["Financial institutions face complex and constantly changing rules, covering areas such as anti-money laundering, sanctions, risk management, reporting and consumer protection. Meeting these requirements manually is expensive and error-prone. RegTech aims to automate and improve compliance.","Common RegTech applications include digital identity verification for customer onboarding, automated screening against sanctions lists, transaction monitoring to detect suspicious activity, regulatory reporting, tracking changes in regulations and monitoring employee communications for misconduct.","For example, a bank might use software that analyses millions of transactions to spot patterns associated with money laundering, flagging suspicious cases for human review rather than relying on simple rules that generate many false alarms.","RegTech can reduce compliance costs, improve accuracy and speed up processes. Challenges include integrating new tools with older systems, ensuring that automated decisions are explainable and keeping up with changing rules. Regulators themselves use similar technology, sometimes called SupTech, for supervision."],"note":"","total":1725,"prev":{"slug":"regressive-tax","term":"Regressive Tax"},"next":{"slug":"regulatory-capital","term":"Regulatory Capital"}}')}}]);